class VirtualDocFS:
    def __init__(self, docs: dict):
        self._docs = dict(docs)

    def list_topics(self) -> list[str]:
        return sorted(self._docs)

    def read_section(self, topic: str) -> str:
        return self._docs.get(topic, 'Not found')


# Test it:
fs = VirtualDocFS({"auth": "# Authentication\nUse API keys.", "setup": "# Setup\nInstall via pip."})
print(fs.list_topics())
print(fs.read_section("auth"))
print(fs.read_section("unknown"))
